import java.util.Scanner;

public class Prepare {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int val = input.nextInt();
        String sequence = input.next();
        int maxCount = 0;
        int currentCount = 0;
        int totalUnderscores = 0;
        boolean insideBrackets = false;
        boolean lastWasLetter = false;

        for (int i = 0; i < sequence.length(); i++) {
            char ch = sequence.charAt(i);
            if ((ch > 96 && ch < 123) || (ch > 64 && ch < 91)) {
                if (insideBrackets && !lastWasLetter)
                    totalUnderscores++;
                if (!insideBrackets)
                    currentCount++;
                if (currentCount > maxCount)
                    maxCount = currentCount;
                lastWasLetter = true;
            } else if (ch == '_') {
                lastWasLetter = false;
                if (currentCount > maxCount)
                    maxCount = currentCount;
                currentCount = 0;
            } else if (ch == '(') {
                lastWasLetter = false;
                insideBrackets = true;
                if (currentCount > maxCount)
                    maxCount = currentCount;
                currentCount = 0;
            } else if (ch == ')') {
                insideBrackets = false;
                lastWasLetter = false;
                if (currentCount > maxCount)
                    maxCount = currentCount;
                currentCount = 0;
            }
        }
        System.out.println(maxCount + " " + totalUnderscores);
        input.close();
    }
}
